function validate([root]) {
  if (!Array.isArray(root)) return 'root is a level-order list with null closing each group of children.';
  if (root.length === 0) return null;
  if (root[0] === null) return 'An empty tree is written as [].';
  if (root.length > 1 && root[1] !== null) return 'The root value must be followed by null.';
  const bad = value => !Number.isInteger(value) || value < 0 || value > 10000;
  if (bad(root[0])) return 'Node values are integers from 0 to 10^4.';
  // depth[k] is the depth of the k-th node in level order; owner is the node whose children are being read.
  const depth = [1];
  let owner = 0;
  for (let i = 2; i < root.length; i++) {
    if (owner >= depth.length) return 'There are more groups of children than nodes to own them.';
    const value = root[i];
    if (value === null) {
      owner++;
      continue;
    }
    if (bad(value)) return 'Node values are integers from 0 to 10^4.';
    depth.push(depth[owner] + 1);
    if (depth[depth.length - 1] > 1000) return 'The tree is at most 1000 levels tall.';
  }
  if (depth.length > 10000) return 'The tree has at most 10^4 nodes.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val, children = []) { this.val = val; this.children = children; }
  }
  // Nodes appear in level order, so nodes[owner] is the parent of the group being read.
  const root = values.length > 0 ? new Node(values[0]) : null;
  const nodes = root ? [root] : [];
  let owner = 0;
  for (let i = 2; i < values.length; i++) {
    if (values[i] === null) {
      owner++;
      continue;
    }
    const child = new Node(values[i]);
    nodes[owner].children.push(child);
    nodes.push(child);
  }
  const links = nodes.map(node => [node.val, node.children, node.children.slice()]);
  const result = solve(root);
  if (result === undefined) throw new Error('The solution did not return a value.');
  const intact = nodes.every((node, i) => node.val === links[i][0] && node.children === links[i][1] && node.children.length === links[i][2].length && node.children.every((child, j) => child === links[i][2][j]));
  if (!intact) throw new Error('The tree must not be modified.');
  if (!Array.isArray(result)) throw new Error('Return an array of node values.');
  return kit.clone(result);
}

