function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(90) : pick(11);
  if (n === 0) return [[]];
  // shape 0 attaches anywhere, 1 grows deep from the newest nodes, 2 keeps the tree wide near the top.
  const shape = pick(3);
  const span = size === 'large' ? 10000 : rand() < 0.5 ? 3 : 50;
  const value = () => pick(span + 1);
  const nodes = [{ val: value(), children: [] }];
  while (nodes.length < n) {
    const parent = shape === 1 ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : shape === 2 ? nodes[pick(Math.min(nodes.length, 4))] : nodes[pick(nodes.length)];
    const child = { val: value(), children: [] };
    parent.children.push(child);
    nodes.push(child);
  }
  // Serialize: root, null, then each node's children in level order followed by null.
  const root = [nodes[0].val, null];
  const queue = [nodes[0]];
  for (let k = 0; k < queue.length; k++) {
    for (const child of queue[k].children) {
      root.push(child.val);
      queue.push(child);
    }
    root.push(null);
  }
  while (root.length > 0 && root[root.length - 1] === null) root.pop();
  return [root];
}
